-- rollback: forward-only; the dropped rows and functions are retired SCAC registry history (the v1-v117 copies, their generated function quartets and the epoch-snapshot family). To inspect them, restore a pre-1033 Neon backup to a branch; nothing at runtime reads them.
-- expand-contract: contract — PR #1798 (2026-10-16) removed every code reader of the historical registry; mcp-server/src/scac-mutation-registry.current.generated.js is the authority and binds to v118 only. No caller in carr-system or doctorcre-app, and no pg_depend or function-body reference in production.
-- lock-review: ops.scac_mutation_registry_entry (244,401 rows, 440 MB) is cut to its 2,817 v118 rows by TRUNCATE + reinsert, holding ACCESS EXCLUSIVE on it and on the empty ops.scac_exact_effect_contract for this transaction (seconds); its only reader is public.v_integrity_digest (health check). ops.scac_mutation_registry_version loses 117 small rows. The 583 function drops touch only pg_proc rows with no dependents. No large DELETE runs.
-- 1033_retire_scac_registry_history.sql
-- WR573.S1.J3 (database audit 2026-10-28, finding F3). The SCAC mutation
-- registry kept a full copy of the catalog per sealed version (118 copies,
-- 244,401 rows) and a generated function quartet per version, long after
-- PR #1798 retired the seal ritual. Keep exactly what live code reads:
--   * the v118 header and its 2,817 entries (public.v_integrity_digest,
--     ops.scac_mutation_catalog_v118_current, the SIEP-18 exact-effect
--     foreign key, ops/scac_mutation_db_inventory.py);
--   * ops.scac_mutation_catalog_v118_current(), the live grant/ACL check;
--   * ops.scac_policy_epoch with its refresh and truncate triggers, because
--     ops.f05_rule_universe() reads max(epoch) for universe_version.
-- Drop the rest:
--   * 578 generated functions: scac_mutation_catalog_vN_current (N<>118),
--     scac_mutation_catalog_vN_live_at_seal, scac_mutation_registration_vN,
--     scac_mutation_registry_vN_seal_available, scac_policy_epoch_snapshot_vN;
--   * the five readers of historical versions: scac_mutation_registration
--     (reads v1), scac_mutation_registry_seal_valid, scac_policy_epoch_snapshot,
--     scac_policy_epoch_chain_state and scac_policy_epoch_status;
--   * the redundant unique (registry_version, entry_digest): entry_digest
--     hashes a contract that carries its ingress_key, so the primary key
--     already implies it;
--   * the v1-v117 header and entry rows.
-- Every DROP is without CASCADE, so an unexpected dependent stops the migration.

-- The exact retired set, named once and used by the grant check and the drop.
create temporary table carr_1033_retired_function on commit drop as
  select p.oid from pg_proc p
   where p.pronamespace = 'ops'::regnamespace
     and (p.proname ~ '^scac_(mutation_catalog_v[0-9]+_live_at_seal|mutation_registration_v[0-9]+|mutation_registry_v[0-9]+_seal_available|policy_epoch_snapshot_v[0-9]+)$'
       or (p.proname ~ '^scac_mutation_catalog_v[0-9]+_current$' and p.proname <> 'scac_mutation_catalog_v118_current')
       or p.proname in ('scac_mutation_registration', 'scac_mutation_registry_seal_valid',
                        'scac_policy_epoch_snapshot', 'scac_policy_epoch_chain_state', 'scac_policy_epoch_status'));

do $retired_set$
begin
  if (select count(*) from pg_temp.carr_1033_retired_function) <> 583 then
    raise exception '1033 FAILED: expected 583 retired SCAC functions, found %',
      (select count(*) from pg_temp.carr_1033_retired_function);
  end if;
  -- No view, default, trigger or other catalog object may depend on them.
  if exists (select 1 from pg_depend d
              where d.refclassid = 'pg_proc'::regclass
                and d.refobjid in (select oid from pg_temp.carr_1033_retired_function)) then
    raise exception '1033 FAILED: a catalog object depends on a retired SCAC function';
  end if;
end $retired_set$;

-- The registration functions and scac_policy_epoch_status carry 472 EXECUTE
-- grants to runtime roles that the v118 catalog check counts. Record them as
-- retired grants (the 0971/0988 pattern) so the check stays current after the
-- functions are gone, and refuse if the live grants differ from this list.
do $retire_registry_grants$
declare
  original jsonb := ops.scac_current_grant_contract();
  live jsonb;
  retired jsonb := $retired$[
