]$retired$::jsonb;
begin
  if ops.scac_mutation_catalog_v118_current() is not true then
    raise exception '1033 FAILED: the SCAC catalog was not current before the retirement';
  end if;
  with recursive connected(oid) as (select oid from pg_roles where rolname~'^carr_' and rolname<>'carr_ci' union select other.oid from connected c join pg_auth_members m on m.roleid=c.oid or m.member=c.oid join pg_roles other on other.oid=case when m.roleid=c.oid then m.member else m.roleid end where other.rolname<>'carr_ci' and not other.rolsuper),
  runtime_roles as (select r.oid,r.rolname from pg_roles r where r.oid in(select oid from connected) and not r.rolsuper),
  functions as (select p.oid,n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) args,p.prosecdef,p.prokind,p.provolatile,p.proparallel,p.proconfig,p.proacl,p.proowner
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where p.oid in (select oid from pg_temp.carr_1033_retired_function)),
  capabilities as (select f.*,acl.grantee,acl.privilege_type,acl.is_grantable from functions f cross join lateral aclexplode(coalesce(f.proacl,acldefault('f',f.proowner))) acl),
  live_observed as (select 'db-function-acl:'||nspname||'.'||proname||'('||args||'):'||coalesce(r.rolname,'public')||':execute' ingress_key,jsonb_build_object('ingress_key','db-function-acl:'||nspname||'.'||proname||'('||args||'):'||coalesce(r.rolname,'public')||':execute','ingress_kind','db_function_acl','signature',nspname||'.'||proname||'('||args||')','security_definer',prosecdef,'function_kind',prokind,'volatility',provolatile,'parallel',proparallel,'config',coalesce(to_jsonb(proconfig),'[]'::jsonb),'grantee',coalesce(r.rolname,'public'),'privilege','execute','grantable',is_grantable) row from capabilities c left join pg_roles r on r.oid=c.grantee where prosecdef and privilege_type='EXECUTE' and grantee<>proowner and (grantee=0 or r.oid in(select oid from runtime_roles)))
  select coalesce(jsonb_agg(row order by ingress_key collate "C"),'[]'::jsonb) into live from live_observed;
  if live is distinct from retired then
    raise exception '1033 FAILED: the live grants on the retired functions differ from the reviewed list (% live, % reviewed)',
      jsonb_array_length(live), jsonb_array_length(retired);
  end if;
  if exists (select 1 from jsonb_array_elements(coalesce(original->'retired_secdef_execute','[]'::jsonb)) old,
                           jsonb_array_elements(retired) new
              where old->>'ingress_key' = new->>'ingress_key') then
    raise exception '1033 FAILED: a registry grant is already retired';
  end if;
  execute format(
    'CREATE OR REPLACE FUNCTION ops.scac_current_grant_contract() RETURNS jsonb '
    'LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS %L',
    'SELECT ' || quote_literal(jsonb_set(original, '{retired_secdef_execute}',
      coalesce(original->'retired_secdef_execute','[]'::jsonb) || retired)::text) || '::jsonb');
end $retire_registry_grants$;

do $drop_registry_functions$
declare
  r record;
  dropped integer := 0;
begin
  for r in select oid::regprocedure as fn from pg_temp.carr_1033_retired_function order by oid::regprocedure::text loop
    execute format('drop function %s', r.fn);
    dropped := dropped + 1;
  end loop;
  raise notice '1033 dropped % retired SCAC functions', dropped;
end $drop_registry_functions$;

alter table ops.scac_mutation_registry_entry
  drop constraint scac_mutation_registry_entry_registry_version_entry_digest_key;

-- Keep only v118. TRUNCATE + reinsert returns the 440 MB to the database at
-- commit; deleting 241,584 rows would leave the file at full size until a
-- VACUUM FULL, which cannot run inside the migration transaction. The
-- exact-effect contract table is truncated with it because its foreign key
-- points here; it must be empty, and the guard below refuses otherwise.
do $registry_rows_guard$
declare v ops.scac_mutation_registry_version%rowtype; kept integer;
begin
  if exists (select 1 from ops.scac_exact_effect_contract) then
    raise exception '1033 FAILED: ops.scac_exact_effect_contract has rows; the registry cannot be truncated';
  end if;
  select * into v from ops.scac_mutation_registry_version where registry_version = 'scac-mutation-registry.v118';
  select count(*) into kept from ops.scac_mutation_registry_entry where registry_version = 'scac-mutation-registry.v118';
  if v.registry_version is null or kept <> v.entry_count then
    raise exception '1033 FAILED: the v118 registry is absent or incomplete (% of % entries)', kept, v.entry_count;
  end if;
end $registry_rows_guard$;

create temporary table carr_1033_registry_v118 on commit drop as
  select * from ops.scac_mutation_registry_entry where registry_version = 'scac-mutation-registry.v118';

alter table ops.scac_exact_effect_contract disable trigger scac_exact_effect_contract_no_truncate;
alter table ops.scac_mutation_registry_entry disable trigger scac_mutation_registry_entry_sealed;
alter table ops.scac_mutation_registry_version disable trigger scac_mutation_registry_version_sealed;

truncate ops.scac_exact_effect_contract, ops.scac_mutation_registry_entry;
insert into ops.scac_mutation_registry_entry select * from pg_temp.carr_1033_registry_v118;
delete from ops.scac_mutation_registry_version where registry_version <> 'scac-mutation-registry.v118';
-- The deletes queue deferred policy-epoch events on the version table, and a
-- table with pending trigger events cannot be altered; settle them now.
set constraints ops.scac_epoch_registry_version immediate;
set constraints ops.scac_epoch_registry_version deferred;

alter table ops.scac_mutation_registry_version enable trigger scac_mutation_registry_version_sealed;
alter table ops.scac_mutation_registry_entry enable trigger scac_mutation_registry_entry_sealed;
alter table ops.scac_exact_effect_contract enable trigger scac_exact_effect_contract_no_truncate;

-- Proof: one version left, its entry set still matches its seal, and the live
-- catalog check still holds with the retired grants recorded.
do $registry_proof$
declare v ops.scac_mutation_registry_version%rowtype; n integer; set_digest text;
begin
  if (select count(*) from ops.scac_mutation_registry_version) <> 1 then
    raise exception '1033 FAILED: more than one registry version remains';
  end if;
  select * into v from ops.scac_mutation_registry_version;
  select count(*), 'sha256:'||encode(public.digest(convert_to(coalesce(string_agg(entry_digest, ','
           order by ingress_key collate "C", entry_digest collate "C"), ''), 'UTF8'), 'sha256'), 'hex')
    into n, set_digest
    from ops.scac_mutation_registry_entry;
  if v.registry_version <> 'scac-mutation-registry.v118' or n <> v.entry_count
     or set_digest is distinct from v.entry_set_digest then
    raise exception '1033 FAILED: the kept v118 entry set no longer matches its seal';
  end if;
  if ops.scac_mutation_catalog_v118_current() is not true then
    raise exception '1033 FAILED: the SCAC catalog is not current after the retirement';
  end if;
end $registry_proof$;
